/* Settings > Labels / Tags: drag reorder and wider names */
.color-manager { width: 100%; max-width: 100%; }
.color-manager-list { display: flex; flex-direction: column; gap: 6px; }
.color-manage { display: flex; gap: 10px; align-items: center; width: 100%; min-width: 0; padding: 5px 8px; border: 1px solid transparent; border-radius: 7px; }
.color-manage.is-dragging { opacity: 0.45; }
.color-manage.is-drop-target { border-color: var(--amber); background: rgba(226, 160, 74, 0.1); }
.color-manage input.color-name { flex: 1 1 auto; min-width: 0; width: 100%; }
.color-manage input[type="color"] { width: 42px; height: 34px; padding: 0; border: 1px solid #444; background: transparent; flex: none; }
.color-manage .btn { flex: none; }
.color-drag-handle, .color-delete { display: inline-flex; align-items: center; justify-content: center; padding: 0; flex: none; border: 0; background: transparent; border-radius: 5px; }
.color-drag-handle { width: 24px; height: 34px; color: var(--dim); cursor: grab; touch-action: none; }
